mapper.select:
select sid, app_id, waste_base_id, generation_ids, warehousing_code, transport_org_id, transport_org_name, transport_person_id, transport_person_name, storage_org_id, storage_org_name, storage_person_id, storage_person_name, storage_position_code, storage_position_name, storage_position_type, container_code, container_name, status, measurement_unit_code, measurement_unit_name, container_number, warehousing_quantity, residue_quantity, warehousing_time, generation_codes, file_id, year_tag, serial_number, remark, update_by, update_time, create_by, create_time, tenant_id, tenant_name, del_flag from hse_hazardous_waste_warehousing where sid in
#{item}
and del_flag=0

select
sid,
app_id,
waste_base_id,
generation_ids,
warehousing_code,
transport_org_id,
transport_org_name,
transport_person_id,
transport_person_name,
storage_org_id,
storage_org_name,
storage_person_id,
storage_person_name,
storage_position_code,
storage_position_name,
storage_position_type,
container_code,
container_name,
status,
measurement_unit_code,
measurement_unit_name,
container_number,
warehousing_quantity,
residue_quantity,
warehousing_time,
generation_codes,
file_id,
year_tag,
serial_number,
remark,
update_by,
update_time,
create_by,
create_time,
tenant_id,
tenant_name,
del_flag

from hse_hazardous_waste_warehousing
where app_id = #{appId} and del_flag=0


    and sid = #{sid}


    and app_id = #{appId}


    and waste_base_id = #{wasteBaseId}


    and generation_ids = #{generationIds}


    and warehousing_code = #{warehousingCode}


    and transport_org_id = #{transportOrgId}


    and transport_org_name = #{transportOrgName}


    and transport_person_id = #{transportPersonId}


    and transport_person_name = #{transportPersonName}


    and storage_org_id = #{storageOrgId}


    and storage_org_name = #{storageOrgName}


    and storage_person_id = #{storagePersonId}


    and storage_person_name = #{storagePersonName}


    and storage_position_code = #{storagePositionCode}


    and storage_position_name = #{storagePositionName}


    and storage_position_type = #{storagePositionType}


    and container_code = #{containerCode}


    and container_name = #{containerName}


    and status = #{status}


    and measurement_unit_code = #{measurementUnitCode}


    and measurement_unit_name = #{measurementUnitName}


    and container_number = #{containerNumber}


    and warehousing_quantity = #{warehousingQuantity}


    and residue_quantity = #{residueQuantity}


    and warehousing_time = #{warehousingTime}


    and generation_codes = #{generationCodes}


    and file_id = #{fileId}


    and year_tag = #{yearTag}


    and serial_number = #{serialNumber}

select
warehousing.sid,
warehousing.app_id as appId,
warehousing.waste_base_id as wasteBaseId,
warehousing.generation_ids as generationIds,
warehousing.warehousing_code as warehousingCode,
warehousing.transport_org_id as transportOrgId,
warehousing.transport_org_name as transportOrgName,
warehousing.transport_person_id as transportPersonId,
warehousing.transport_person_name as transportPersonName,
warehousing.storage_org_id as storageOrgId,
warehousing.storage_org_name as storageOrgName,
warehousing.storage_person_id as storagePersonId,
warehousing.storage_person_name as storagePersonName,
warehousing.storage_position_code as storagePositionCode,
warehousing.storage_position_name as storagePositionName,
warehousing.storage_position_type as storagePositionType,
warehousing.container_code as containerCode,
warehousing.container_name as containerName,
warehousing.status,
warehousing.measurement_unit_code as measurementUnitCode,
warehousing.measurement_unit_name as measurementUnitName,
warehousing.container_number as containerNumber,
warehousing.warehousing_quantity as warehousingQuantity,
warehousing.residue_quantity as residueQuantity,
warehousing.warehousing_time as warehousingTime,
warehousing.generation_codes as generationCodes,
warehousing.file_id as fileId,
warehousing.year_tag,
warehousing.serial_number,
warehousing.remark,
warehousing.update_by,
warehousing.update_time,
warehousing.create_by,
warehousing.create_time,
warehousing.tenant_id,
warehousing.tenant_name,
warehousing.del_flag,

base.waste_name as wasteBaseName,
directory.waste_code as wasteCode,
directory.name as wasteName,
directory.type as wasteType

from hse_hazardous_waste_warehousing warehousing
left join hse_hazardous_waste_base base on base.sid = warehousing.waste_base_id
left join hse_hazardous_waste_directory directory on base.directory_id = directory.sid

where warehousing.app_id = #{appId} and warehousing.del_flag = 0
and base.app_id = #{appId} and base.del_flag = 0
and directory.app_id = #{appId} and directory.del_flag = 0


    and (
    warehousing.warehousing_code like concat('%',#{keyWord},'%')
    or warehousing.storage_person_name like concat('%',#{keyWord},'%')
    or base.waste_name like concat('%',#{keyWord},'%')
    or directory.waste_code like concat('%',#{keyWord},'%')
    )




    and warehousing.waste_base_id = #{wasteBaseId}


    and warehousing.generation_ids = #{generationIds}


    and warehousing.warehousing_code = #{warehousingCode}


    and warehousing.transport_org_id = #{transportOrgId}


    and warehousing.transport_org_name = #{transportOrgName}


    and warehousing.transport_person_id = #{transportPersonId}


    and warehousing.transport_person_name = #{transportPersonName}


    and warehousing.storage_org_id = #{storageOrgId}


    and warehousing.storage_org_name = #{storageOrgName}


    and warehousing.storage_person_id = #{storagePersonId}


    and warehousing.storage_person_name = #{storagePersonName}


    and warehousing.storage_position_code = #{storagePositionCode}


    and warehousing.storage_position_name = #{storagePositionName}


    and warehousing.storage_position_type = #{storagePositionType}


    and warehousing.container_code = #{containerCode}


    and warehousing.container_name = #{containerName}


    and warehousing.status = #{status}


    and warehousing.measurement_unit_code = #{measurementUnitCode}


    and warehousing.measurement_unit_name = #{measurementUnitName}


    and warehousing.container_number = #{containerNumber}


    and warehousing.warehousing_quantity = #{warehousingQuantity}


    and warehousing.residue_quantity = #{residueQuantity}


    and warehousing.warehousing_time = #{warehousingTime}


    and warehousing.generation_codes = #{generationCodes}


    and warehousing.file_id = #{fileId}


    and warehousing.year_tag = #{yearTag}


    and warehousing.serial_number = #{serialNumber}




    and warehousing.warehousing_time >= #{searchStartDate}


    and warehousing.warehousing_time <= #{searchEndDate}


order by warehousing.create_time desc

select sid, app_id, waste_base_id, generation_ids, warehousing_code, transport_org_id, transport_org_name, transport_person_id, transport_person_name, storage_org_id, storage_org_name, storage_person_id, storage_person_name, storage_position_code, storage_position_name, storage_position_type, container_code, container_name, status, measurement_unit_code, measurement_unit_name, container_number, warehousing_quantity, residue_quantity, warehousing_time, generation_codes, file_id, year_tag, serial_number, remark, update_by, update_time, create_by, create_time, tenant_id, tenant_name, del_flag
from hse_hazardous_waste_warehousing where app_id = #{appId}
and year_tag = #{yearTag}
order by serial_number desc limit 1;
